input.command:
grep -n -iE "result|showing|load more|page " db-fs-interact.txt | head; firecrawl interact --timeout 120 --code '
await page.getByRole("checkbox",{name:"Financial Services"}).check({force:true});
await page.getByRole("checkbox",{name:"Case Study"}).check({force:true});
await page.getByRole("button",{name:"Apply Selected Filters"}).click();
await page.waitForTimeout(4000);
for(let i=0;i<30;i++){const b=page.getByRole("button",{name:/load more|show more/i});if(await b.count()&&await b.first().isVisible()){await b.first().click();await page.waitForTimeout(1500);}else break;}
const links=await page.$$eval("a[href*=\"/customers/\"]",as=>as.map(a=>a.href+" | "+a.textContent.trim().slice(0,80)));
const txt=await page.evaluate(()=>[...document.body.innerText.matchAll(/.{0,40}(results|showing).{0,40}/gi)].map(m=>m[0]).join("\n"));
console.log(txt);console.log(links.join("\n"));
' -o db-fs-code.txt; wc -l db-fs-code.txt; head -80 db-fs-code.txt

