input.command:
firecrawl interact -s 01a1555f-8171-77f0-83be-bd3ab3a812c4 --timeout 120 --code '
await page.getByRole("checkbox",{name:"Financial Services"}).check({force:true});
await page.getByRole("checkbox",{name:"Case Study"}).check({force:true});
await page.getByRole("button",{name:"Apply Selected Filters"}).click();
await page.waitForTimeout(4000);
const out=[];
for(let p=0;p<15;p++){
 out.push(...await page.$$eval("a[href*=\"/customers/\"]",as=>as.map(a=>a.href.split("?")[0]+" | "+(a.getAttribute("aria-label")||a.textContent).trim().slice(0,60))));
 const n=page.getByRole("link",{name:/next/i});
 if(await n.count()&&await n.first().isVisible()){await n.first().click();await page.waitForTimeout(2500);}else break;
}
const pg=await page.$$eval("a[aria-label^=\"Go to page\"]",as=>as.map(a=>a.getAttribute("aria-label")));
console.log("PAGES",pg.join(","));console.log([...new Set(out)].join("\n"));
' -o db-fs-code.txt; wc -l db-fs-code.txt; head -90 db-fs-code.txt

